// generate-sdk-tables.swift
//
// Generates the Swift error-code table and flag constants from the
// language-neutral JSON files shipped with every Senzing runtime:
//
//   <runtime>/er/sdk/szerrors.json -> Sources/SenzingSDK/Generated/SzErrorCodes.swift
//   <runtime>/er/sdk/szflags.json  -> Sources/SenzingSDK/Generated/SzFlags+Constants.swift
//
// Usage (from the repository root):
//
//   swift tools/generate-sdk-tables.swift [<runtime er directory>] [<output directory>]
//
// The runtime directory defaults to $SENZING_DIR, then the platform default.
// The generated files are committed; CI regenerates them against the installed
// runtime and fails if they drift.

import Foundation

struct ErrorEntry: Decodable {
    let code: String
    let `class`: String
    let name: String
    let comment: String
}

struct FlagEntry: Decodable {
    let symbol: String
    let altSymbol: String
    let value: Int64
    let hexValue: String
    let bits: [Int]
    let definition: FlagDefinition
    let groups: [String]
    let altGroups: [String]
}

/// A flag is either a single bit (`"1 << 26"`) or a union of other flags.
enum FlagDefinition: Decodable {
    case expression(String)
    case union([String])

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let list = try? container.decode([String].self) {
            self = .union(list)
        } else {
            self = .expression(try container.decode(String.self))
        }
    }
}

/// Maps the szerrors.json class names to `SzErrorKind` case names.
let kindForClass: [String: String] = [
    "SzError": "general",
    "SzBadInputError": "badInput",
    "SzNotFoundError": "notFound",
    "SzUnknownDataSourceError": "unknownDataSource",
    "SzConfigurationError": "configuration",
    "SzReplaceConflictError": "replaceConflict",
    "SzRetryableError": "retryable",
    "SzDatabaseConnectionLostError": "databaseConnectionLost",
    "SzDatabaseTransientError": "databaseTransient",
    "SzRetryTimeoutExceededError": "retryTimeoutExceeded",
    "SzUnrecoverableError": "unrecoverable",
    "SzDatabaseError": "database",
    "SzLicenseError": "license",
    "SzNotInitializedError": "notInitialized",
    "SzUnhandledError": "unhandled",
]

/// `SzEntityIncludeEntityName` -> `entityIncludeEntityName`.
func swiftName(_ altSymbol: String) -> String {
    var name = altSymbol
    if name.hasPrefix("Sz") {
        name.removeFirst(2)
    }
    return name.prefix(1).lowercased() + name.dropFirst()
}

/// `SzWhyRecordInEntityFlags` -> `whyRecordInEntity`.
func groupName(_ altGroup: String) -> String {
    var name = swiftName(altGroup)
    if name.hasSuffix("Flags") {
        name.removeLast(5)
    }
    return name
}

func hex(_ value: Int64) -> String {
    let digits = String(UInt64(bitPattern: value), radix: 16, uppercase: true)
    let padded = String(repeating: "0", count: max(0, 16 - digits.count)) + digits
    var grouped = ""
    for (index, character) in padded.enumerated() {
        if index > 0 && index % 4 == 0 {
            grouped += "_"
        }
        grouped.append(character)
    }
    return "0x" + grouped
}

let header = """
    // @generated by tools/generate-sdk-tables.swift. DO NOT EDIT.
    //
    // Regenerate from an installed Senzing runtime with:
    //   swift tools/generate-sdk-tables.swift

    """

func generateErrors(from url: URL) throws -> String {
    let entries = try JSONDecoder().decode([String: ErrorEntry].self, from: Data(contentsOf: url))
    var rows: [(Int64, String, String)] = []
    for (key, entry) in entries {
        guard let code = Int64(key) else {
            throw CocoaError(.coderInvalidValue, userInfo: [NSDebugDescriptionErrorKey: "bad code \(key)"])
        }
        guard let kind = kindForClass[entry.class] else {
            throw CocoaError(
                .coderInvalidValue,
                userInfo: [NSDebugDescriptionErrorKey: "unknown error class \(entry.class) for \(key)"]
            )
        }
        if kind != "general" {
            rows.append((code, kind, entry.name))
        }
    }
    rows.sort { $0.0 < $1.0 }
    var out = header
    out += """

        extension SzErrorKind {
            /// The `szerrors.json` assignment of native error codes to error kinds.
            ///
            /// Codes absent from this table map to ``SzErrorKind/general``.
            static let kindsByErrorCode: [Int64: SzErrorKind] = [

        """
    for (code, kind, name) in rows {
        out += "        \(code): .\(kind),  // \(name)\n"
    }
    out += """
            ]
        }

        """
    return out
}

func generateFlags(from url: URL) throws -> String {
    let entries = try JSONDecoder().decode([FlagEntry].self, from: Data(contentsOf: url))
    var out = header
    out += "\nextension SzFlags {\n"
    for entry in entries {
        let name = swiftName(entry.altSymbol)
        var doc = "    /// `\(entry.symbol)`"
        switch entry.definition {
        case .expression(let expression):
            doc += " (`\(expression)`)."
        case .union(let members):
            doc += ": the union of " + members.map { "`\($0)`" }.joined(separator: ", ") + "."
        }
        out += doc + "\n"
        if !entry.altGroups.isEmpty {
            let groups = entry.altGroups.map { "``SzFlagUsageGroup/\(groupName($0))``" }
            out += "    ///\n    /// Usage groups: " + groups.joined(separator: ", ") + ".\n"
        }
        if entry.value == 0 {
            out += "    public static let \(name): SzFlags = []\n\n"
        } else {
            out += "    public static let \(name) = SzFlags(rawValue: \(hex(entry.value)))\n\n"
        }
    }
    out.removeLast()
    out += "}\n"

    // Usage groups: a group's flags are the single-bit flags that list it
    // (aliases such as SZ_SEARCH_INCLUDE_RESOLVED count: they are one bit).
    var groupMembers: [String: [String]] = [:]
    var groupBits: [String: Int64] = [:]
    for entry in entries {
        for group in entry.altGroups where groupMembers[group] == nil {
            groupMembers[group] = []
        }
    }
    for entry in entries {
        guard entry.bits.count == 1 else {
            continue
        }
        for group in entry.altGroups {
            groupMembers[group, default: []].append(swiftName(entry.altSymbol))
            groupBits[group, default: 0] |= entry.value
        }
    }
    let groups = groupMembers.keys.sorted()
    out += """

        /// The Senzing API usage groups: which flags each engine method accepts.
        public enum SzFlagUsageGroup: String, CaseIterable, Sendable {

        """
    for group in groups {
        out += "    /// `\(group)`.\n"
        out += "    case \(groupName(group)) = \"\(group)\"\n"
    }
    out += """

            /// Every flag that applies to this usage group (empty when the
            /// group's methods take no flags).
            public var allFlags: SzFlags {
                switch self {

        """
    for group in groups {
        let bits = groupBits[group] ?? 0
        let value = bits == 0 ? "[]" : "SzFlags(rawValue: \(hex(bits)))"
        out += "        case .\(groupName(group)): \(value)\n"
    }
    out += """
                }
            }
        }

        """
    return out
}

let arguments = CommandLine.arguments
let environment = ProcessInfo.processInfo.environment
let runtime = arguments.count > 1 ? arguments[1] : (environment["SENZING_DIR"] ?? "/opt/senzing/er")
let outputDirectory = arguments.count > 2 ? arguments[2] : "Sources/SenzingSDK/Generated"
let sdkDirectory = URL(fileURLWithPath: runtime).appendingPathComponent("sdk")
let outputURL = URL(fileURLWithPath: outputDirectory)

do {
    try FileManager.default.createDirectory(at: outputURL, withIntermediateDirectories: true)
    let errors = try generateErrors(from: sdkDirectory.appendingPathComponent("szerrors.json"))
    try errors.write(to: outputURL.appendingPathComponent("SzErrorCodes.swift"), atomically: true, encoding: .utf8)
    let flags = try generateFlags(from: sdkDirectory.appendingPathComponent("szflags.json"))
    try flags.write(to: outputURL.appendingPathComponent("SzFlags+Constants.swift"), atomically: true, encoding: .utf8)
    print("Generated SzErrorCodes.swift and SzFlags+Constants.swift from \(sdkDirectory.path)")
} catch {
    FileHandle.standardError.write(Data("error: \(error)\n".utf8))
    exit(1)
}
